		"forkDigest":       fmt.Sprintf("%#x", e.ForkDigest),
		"maxBlobsPerBlock": e.MaxBlobsPerBlock,
		"epoch":            e.Epoch,
		"bpoEpoch":         e.BPOEpoch,
		"isFork":           e.isFork,
		"forkEnum":         version.String(e.VersionEnum),
		"sanity":           fmt.Sprintf("%#x", root),
		"gvr":              fmt.Sprintf("%#x", gvr),
	}
	return fields
}

